{
  "cvars": {
    "ivs": [
      {
        "description": "Instructor physical attractiveness score (average of six raters, mean-centered in the transform). Higher = more attractive. This is the main independent variable (beauty).",
        "columns": [
          "Beauty",
          "Beauty_c"
        ]
      }
    ],
    "dv": {
      "description": "Course overall teaching evaluation score (1 to 5). Higher = better evaluation.",
      "columns": [
        "Eval"
      ]
    },
    "controls": [
      {
        "description": "Instructor gender (female = 1, male = 0). Included as a control and tested as a moderator (interaction) with Beauty.",
        "is_moderator": true,
        "moderator_on": "Beauty",
        "columns": [
          "Female"
        ]
      },
      {
        "description": "Whether instructor is a racial/ethnic minority (yes = 1, no = 0). Control for possible systematic differences in ratings.",
        "is_moderator": false,
        "columns": [
          "Minority"
        ]
      },
      {
        "description": "Instructor age in years (mean-centered in the transform). Control for experience / age-related effects.",
        "is_moderator": false,
        "columns": [
          "Age",
          "Age_c"
        ]
      },
      {
        "description": "Indicator for single-credit elective courses (single-credit = 1, other = 0). Controls for course type that can affect evaluations.",
        "is_moderator": false,
        "columns": [
          "SingleCredit"
        ]
      },
      {
        "description": "Indicator for course division (upper-division = 1, lower-division = 0). Controls for course level differences.",
        "is_moderator": false,
        "columns": [
          "UpperDivision"
        ]
      },
      {
        "description": "Whether the instructor is a native English speaker (yes = 1, no = 0). Controls for possible language effects on ratings.",
        "is_moderator": false,
        "columns": [
          "NativeEnglish"
        ]
      },
      {
        "description": "Whether the instructor is on the tenure track (yes = 1, no = 0). Controls for job status differences.",
        "is_moderator": false,
        "columns": [
          "TenureTrack"
        ]
      },
      {
        "description": "Number of students who participated in the evaluation (logged). Controls for precision and class-size effects.",
        "is_moderator": false,
        "columns": [
          "NumStudentsRated",
          "LogNumStudents"
        ]
      },
      {
        "description": "Total number of students enrolled in the course (logged). Controls for course enrollment size.",
        "is_moderator": false,
        "columns": [
          "Enrollment",
          "LogEnrollment"
        ]
      },
      {
        "description": "Instructor identifier used as a fixed effect (categorical). Controls for unobserved instructor-specific heterogeneity.",
        "is_moderator": false,
        "columns": [
          "InstructorID"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Transform raw dataset to variables used in modeling.\n    Input: original dataframe with columns feature1..feature13 (see schema)\n    Output: dataframe with columns used in the statistical model:\n      - Beauty, Beauty_c\n      - Eval\n      - Female, Minority, Age, Age_c, SingleCredit, UpperDivision, NativeEnglish, TenureTrack\n      - NumStudentsRated, LogNumStudents, Enrollment, LogEnrollment\n      - InstructorID\n\n    The function drops rows missing the key dependent/independent variables and required controls.\n    \"\"\"\n    df = df.copy()\n\n    # Ensure numeric columns are numeric and drop rows with missing outcome or main predictor\n    df['feature6'] = pd.to_numeric(df['feature6'], errors='coerce')  # beauty rating\n    df['feature7'] = pd.to_numeric(df['feature7'], errors='coerce')  # eval score\n    df = df.dropna(subset=['feature6', 'feature7'])\n\n    # Dependent and independent variables\n    df['Beauty'] = df['feature6']\n    df['Eval'] = df['feature7']\n\n    # Controls: map textual categories to binaries and coerce numerics\n    # feature2: minority (\"yes\"/\"no\")\n    df['Minority'] = df['feature2'].astype(str).str.strip().str.lower().map({'yes': 1, 'no': 0})\n    # feature4: gender (\"male\"/\"female\") -> Female indicator\n    df['Female'] = df['feature4'].astype(str).str.strip().str.lower().map({'female': 1, 'male': 0})\n    # feature3: age\n    df['Age'] = pd.to_numeric(df['feature3'], errors='coerce')\n    # feature5: single-credit elective (samples show 'single' or 'more') -> treat 'single' as single-credit elective\n    df['SingleCredit'] = df['feature5'].astype(str).str.strip().str.lower().map({'single': 1, 'more': 0})\n    # feature8: course division ('upper'/'lower')\n    df['UpperDivision'] = df['feature8'].astype(str).str.strip().str.lower().map({'upper': 1, 'lower': 0})\n    # feature9: native english ('yes'/'no')\n    df['NativeEnglish'] = df['feature9'].astype(str).str.strip().str.lower().map({'yes': 1, 'no': 0})\n    # feature10: tenure track ('yes'/'no')\n    df['TenureTrack'] = df['feature10'].astype(str).str.strip().str.lower().map({'yes': 1, 'no': 0})\n\n    # Numeric course-size controls\n    df['NumStudentsRated'] = pd.to_numeric(df['feature11'], errors='coerce')\n    df['Enrollment'] = pd.to_numeric(df['feature12'], errors='coerce')\n\n    # Instructor identifier for fixed effects\n    df['InstructorID'] = df['feature13']\n\n    # Log transforms (clip at 1 to avoid log(0))\n    df['LogNumStudents'] = np.log(df['NumStudentsRated'].clip(lower=1))\n    df['LogEnrollment'] = np.log(df['Enrollment'].clip(lower=1))\n\n    # Center continuous covariates to aid interpretation\n    df['Beauty_c'] = df['Beauty'] - df['Beauty'].mean()\n    df['Age_c'] = df['Age'] - df['Age'].mean()\n\n    # Drop rows with remaining missing values in model columns\n    required_cols = [\n        'Beauty', 'Beauty_c', 'Eval', 'Female', 'Minority', 'Age', 'Age_c',\n        'SingleCredit', 'UpperDivision', 'NativeEnglish', 'TenureTrack',\n        'NumStudentsRated', 'LogNumStudents', 'Enrollment', 'LogEnrollment', 'InstructorID'\n    ]\n    df = df.dropna(subset=required_cols)\n\n    # Ensure InstructorID is treated as categorical-friendly (keep as is; C(...) will be used in formula)\n    df['InstructorID'] = df['InstructorID'].astype('category')\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> Any:\n    \"\"\"\n    Fit an OLS model estimating the effect of beauty on teaching evaluations.\n\n    Model specification (main):\n      Eval ~ Beauty_c + Female + Minority + Age_c + SingleCredit + UpperDivision\n             + NativeEnglish + TenureTrack + LogNumStudents + LogEnrollment\n             + Beauty_c:Female + C(InstructorID)\n\n    - Uses heteroskedasticity-robust standard errors (HC3).\n    - Returns the fitted results object (statsmodels.regression.linear_model.RegressionResultsWrapper).\n    \"\"\"\n    import statsmodels.formula.api as smf\n\n    # Formula includes an interaction between beauty and female (gender as moderator) and instructor fixed effects\n    formula = (\n        'Eval ~ Beauty_c + Female + Minority + Age_c + SingleCredit + UpperDivision '\n        '+ NativeEnglish + TenureTrack + LogNumStudents + LogEnrollment '\n        '+ ' + Beauty_c:Female + C(InstructorID)'\n    )\n\n    results = smf.ols(formula, data=df).fit(cov_type='HC3')\n\n    # The caller can inspect results.summary() or use results.params, results.bse, etc.\n    return results\n"
}

